/**
 * Generates the binary files of the demo fixture (`assets/logo.png`, `data/snapshot.bin`).
 *
 * They are produced by code rather than copied from anywhere so their provenance is clear
 * and they can be regenerated byte for byte: `bun src/app/demo/generate-assets.ts`.
 * A test compares the committed files with this output.
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { deflateSync } from "node:zlib";
import { DEFAULT_FIXTURE_DIR } from "./fixture";

const PNG_SIGNATURE = Uint8Array.of(0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a);

let crcTable: Uint32Array | undefined;

function crc32(bytes: Uint8Array): number {
  if (!crcTable) {
    crcTable = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      crcTable[n] = c >>> 0;
    }
  }
  let crc = 0xffffffff;
  for (const byte of bytes) crc = crcTable[(crc ^ byte) & 0xff]! ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(12 + data.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, data.length);
  out.set(new TextEncoder().encode(type), 4);
  out.set(data, 8);
  // The CRC covers the chunk type and data, not the length.
  view.setUint32(8 + data.length, crc32(out.subarray(4, 8 + data.length)));
  return out;
}

/** Encodes 8-bit RGBA pixels (row-major, `width * height * 4` bytes) as a PNG. */
export function encodePng(width: number, height: number, rgba: Uint8Array): Uint8Array {
  if (rgba.length !== width * height * 4) {
    throw new RangeError(`Expected ${width * height * 4} bytes of RGBA data, got ${rgba.length}`);
  }
  const header = new Uint8Array(13);
  const headerView = new DataView(header.buffer);
  headerView.setUint32(0, width);
  headerView.setUint32(4, height);
  header[8] = 8; // bit depth
  header[9] = 6; // colour type: truecolour with alpha
  // Compression, filter and interlace methods stay 0.

  // Every scanline is prefixed with filter type 0 (none); simple and deterministic.
  const raw = new Uint8Array(height * (width * 4 + 1));
  for (let y = 0; y < height; y++) {
    raw.set(rgba.subarray(y * width * 4, (y + 1) * width * 4), y * (width * 4 + 1) + 1);
  }
  const parts = [
    PNG_SIGNATURE,
    chunk("IHDR", header),
    chunk("IDAT", new Uint8Array(deflateSync(raw, { level: 9 }))),
    chunk("IEND", new Uint8Array(0)),
  ];
  const png = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let offset = 0;
  for (const part of parts) {
    png.set(part, offset);
    offset += part.length;
  }
  return png;
}

function mix(a: number, b: number, t: number): number {
  return Math.round(a + (b - a) * t);
}

/** A 32x32 logo: a diagonal indigo-to-teal gradient with a light orbit ring. */
export function createLogoPng(size = 32): Uint8Array {
  const pixels = new Uint8Array(size * size * 4);
  const from = [0x3b, 0x2f, 0x8f];
  const to = [0x1f, 0xb5, 0xa8];
  const centre = (size - 1) / 2;
  const ringRadius = size * 0.34;
  const planet = [0xff, 0xc8, 0x57];
  const planetX = centre + ringRadius * Math.cos(-Math.PI / 4);
  const planetY = centre + ringRadius * Math.sin(-Math.PI / 4);
  const planetRadius = size * 0.08;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const t = (x + y) / (2 * (size - 1));
      const distance = Math.hypot(x - centre, y - centre);
      // Anti-aliased ring, about 1.5 px wide, blended towards white.
      const ring = Math.max(0, 1 - Math.abs(distance - ringRadius) / 1.5) * 0.85;
      const dot = Math.min(1, Math.max(0, planetRadius + 0.5 - Math.hypot(x - planetX, y - planetY)));
      const index = (y * size + x) * 4;
      for (let c = 0; c < 3; c++) {
        const base = mix(mix(from[c]!, to[c]!, t), 0xf4, ring);
        pixels[index + c] = mix(base, planet[c]!, dot);
      }
      pixels[index + 3] = 0xff;
    }
  }
  return encodePng(size, size, pixels);
}

/**
 * A small binary blob in a made-up "ORBT" snapshot format: magic, version, record count,
 * then fixed-size records filled from a seeded xorshift generator.
 */
export function createSnapshotBin(records = 30): Uint8Array {
  const recordSize = 8;
  const out = new Uint8Array(8 + records * recordSize);
  const view = new DataView(out.buffer);
  out.set(new TextEncoder().encode("ORBT"), 0);
  view.setUint16(4, 2, true);
  view.setUint16(6, records, true);
  let state = 0x2f6b_1d3a;
  for (let i = 8; i < out.length; i++) {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    out[i] = state & 0xff;
  }
  return out;
}

export const GENERATED_ASSETS: Readonly<Record<string, () => Uint8Array>> = {
  "assets/logo.png": () => createLogoPng(),
  "data/snapshot.bin": () => createSnapshotBin(),
};

/** Writes every generated asset into `fixtureDir`; returns the relative paths written. */
export function writeDemoAssets(fixtureDir: string = DEFAULT_FIXTURE_DIR): string[] {
  const written: string[] = [];
  for (const [relativePath, create] of Object.entries(GENERATED_ASSETS)) {
    writeFileSync(join(fixtureDir, relativePath), create());
    written.push(relativePath);
  }
  return written;
}

if (import.meta.main) {
  for (const path of writeDemoAssets()) console.log(`wrote ${path}`);
}
